import os, pty, sys, time, select, fcntl, termios, struct, signal
sys.path.insert(0,'/tmp/rec')
from term import Term

class TSession:
    """Timestamped recorder: keeps list of (t, bytes) chunks with tight read loop."""
    def __init__(self, args, rows=30, cols=100, exe='./executable', settle=0.6):
        self.rows=rows; self.cols=cols
        self.chunks=[]   # (t_rel, bytes)
        self.t0=time.time()
        self.pid, self.fd = pty.fork()
        if self.pid==0:
            env=dict(os.environ); env['TERM']='xterm-256color'
            env['COLUMNS']=str(cols); env['LINES']=str(rows)
            os.execvpe(exe,[exe]+list(args),env)
        fcntl.ioctl(self.fd, termios.TIOCSWINSZ, struct.pack('HHHH', rows, cols, 0,0))
        self.alive=True
        self.pump(settle)
    def pump(self, t=0.25):
        end=time.time()+t
        while True:
            rem=end-time.time()
            if rem<=0: break
            r,_,_=select.select([self.fd],[],[],min(rem,0.002))
            if r:
                try: d=os.read(self.fd,65536)
                except OSError: self.alive=False; break
                if not d: self.alive=False; break
                self.chunks.append((time.time()-self.t0, d))
    def send(self,s,wait=0.0):
        os.write(self.fd, s if isinstance(s,bytes) else s.encode())
        if wait: self.pump(wait)
    def raw(self):
        return b''.join(c for _,c in self.chunks)
    def close(self):
        try: os.kill(self.pid, signal.SIGKILL)
        except Exception: pass
        try: os.waitpid(self.pid,0)
        except Exception: pass

def frames(chunks, rows=30, cols=100):
    """Replay chunks cumulatively; yield (t, Term-copy-text) after each chunk."""
    t=Term(rows,cols)
    out=[]
    for ts,d in chunks:
        t.feed(d)
        out.append((ts, [''.join(c.ch for c in row) for row in t.grid]))
    return out

def rowsig(gridlines, rlist):
    return '\n'.join(gridlines[r].rstrip() for r in rlist)
